/* The logo counter wraps here, and the idle timers count to TITLE_IDLE_FRAMES. */
#define TITLE_LOGO_WRAP 108000
#define TITLE_IDLE_FRAMES 1800
/* Frames a fade runs for, and the number of title blocks in title_block_entries. */
#define TITLE_FADE_FRAMES 10
#define TITLE_BLOCK_COUNT 4
/* The logo blink: frames to wait before it starts, one blink cycle, its on part, and its end. */
#define TITLE_LOGO_WAIT_FRAMES 30
#define TITLE_BLINK_PERIOD 30
#define TITLE_BLINK_ON 15
#define TITLE_BLINK_END_FRAMES 90
/* The new player's money and stamina. */
#define TITLE_START_GOLD 500
#define TITLE_START_STAMINA 100

/* One of the three title pictures. */
typedef struct TitleImage {
    u8 bytes[0x1800];
} TitleImage;

typedef struct {
    u8 bytes[0xD1C];
} TitleSpriteFile;

typedef struct {
    u8 bytes[0x13DC];
} TitleImageBuffer;

typedef struct {
    s32 next;
    DemoRecording *src;
} TitleBlockEntry;

