static void (*title_step_handlers[7])(void) = {
    title_enter_state, title_state_show_image, title_load_step, title_sequence_step,
    title_exit_fade_begin, title_exit_fade_wait, title_exit_finish,
};

/* The field layout title_fill_field_layout copies: one of three random farms for a
 * new game (rand_range(3)), or the demo's (TITLE_LAYOUT_DEMO, a demo start). */
enum TitleFieldLayout {
    TITLE_LAYOUT_NEW_0 = 0,
    TITLE_LAYOUT_NEW_1 = 1,
    TITLE_LAYOUT_NEW_2 = 2,
    TITLE_LAYOUT_DEMO = 3,
};

/* The steps of title_load_step, in order. */
enum TitleLoadStep {
    TITLE_LOAD_FADE_WAIT = 0,
    TITLE_LOAD_BLOCK_START = 1,
    TITLE_LOAD_BLOCK_WAIT = 2,
    TITLE_LOAD_SMALL_START = 3,
    TITLE_LOAD_SMALL_WAIT = 4,
    TITLE_LOAD_IMAGE_START = 5,
    TITLE_LOAD_IMAGE_WAIT = 6,
    TITLE_LOAD_MUSIC = 7,
    TITLE_LOAD_SOUND_WAIT = 8,
    TITLE_LOAD_SOUND_FADE_WAIT = 9,
    TITLE_LOAD_FUNC = 10,
    TITLE_LOAD_COPY_BLOCK = 11,
    TITLE_LOAD_SCENE_FADE_WAIT = 12,
};

/* The steps of title_sequence_step. The name entry runs player name, voice,
 * farm name, dog name, birthday; a "no" on the birthday starts it over. */
enum TitleSequenceStep {
    TITLE_SEQ_FADE_IN = 0,
    TITLE_SEQ_FADE_IN_WAIT = 1,
    TITLE_SEQ_IDLE = 2,
    TITLE_SEQ_PRESS_FADE_WAIT = 3,
    TITLE_SEQ_SCENE_FADE_IN = 4,
    TITLE_SEQ_SCENE_FADE_WAIT = 5,
    TITLE_SEQ_START_WAIT = 6,
    TITLE_SEQ_MENU = 7,
    TITLE_SEQ_NEW_GAME = 8,
    TITLE_SEQ_CONTINUE_FADE_WAIT = 9,
    TITLE_SEQ_CONTINUE_SOUND_WAIT = 10,
    TITLE_SEQ_NEW_GAME_TEXT_OPEN = 11,
    TITLE_SEQ_NEW_GAME_TEXT_WAIT = 12,
    TITLE_SEQ_PLAYER_NAME_OPEN = 13,
    TITLE_SEQ_PLAYER_NAME_START = 14,
    TITLE_SEQ_PLAYER_NAME_ENTRY = 15,
    TITLE_SEQ_VOICE_OPEN = 16,
    TITLE_SEQ_VOICE_WAIT = 17,
    TITLE_SEQ_VOICE_PLAY = 18,
    TITLE_SEQ_FARM_NAME_OPEN = 19,
    TITLE_SEQ_FARM_NAME_START = 20,
    TITLE_SEQ_FARM_NAME_ENTRY = 21,
    TITLE_SEQ_DOG_NAME_OPEN = 22,
    TITLE_SEQ_DOG_NAME_START = 23,
    TITLE_SEQ_DOG_NAME_ENTRY = 24,
    TITLE_SEQ_BIRTHDAY_OPEN = 25,
    TITLE_SEQ_BIRTHDAY_CONFIRM = 26,
    TITLE_SEQ_NEW_GAME_FADE_WAIT = 27,
    TITLE_SEQ_NEW_GAME_LEAVE = 28,
    TITLE_SEQ_RESTART_WAIT = 29,
    TITLE_SEQ_DEMO_FADE_OUT = 33,
    TITLE_SEQ_DEMO_FADE_WAIT = 34,
    TITLE_SEQ_DEMO_LEAVE = 35,
};

/* The two rows of the title menu: TITLE_MENU_NEW_GAME starts a new game (the
 * name entry), TITLE_MENU_CONTINUE continues a saved one (TITLE_SEQ_CONTINUE_*). */
enum TitleMenuRow {
    TITLE_MENU_NEW_GAME = 0,
    TITLE_MENU_CONTINUE = 1,
};

/* Current step of the intro. Each step sets the next one. */
static void (*title_step_fn)(void) = title_logo_begin;
static s16 title_load_state = TITLE_LOAD_FADE_WAIT;
/* Which of the two title menus is shown. */
static s16 title_menu_page = TITLE_MENU_CONTINUE;

static s32 title_logo_frames = 0;
static s32 title_idle_frames = 0;
static s16 title_sequence_state = TITLE_SEQ_FADE_IN;
static s16 title_sequence_done = 0;
static s32 title_saved_flags = 0;
static s16 title_anim_a_timer = 0;
static s16 title_anim_b_timer = 0;
static s16 title_anim_c_timer = 0;
static s16 title_column_a_count = 0;
static s16 title_column_b_count = 0;
static s16 title_column_c_count = 0;
static s16 title_logo_slide = -160;
static s16 title_drop_count = 48;
static s16 title_logo_wipe = 320;
static TitleImage *title_image_ptrs[3] = {
    (TitleImage *)title_image_0, (TitleImage *)title_image_1, (TitleImage *)title_image_2,
};
static s16 title_scroll_a = 0;
static s16 title_scroll_b = 0;
static s32 title_caption_offsets[4] = {
    offsetof(TextMessages, your_name), offsetof(TextMessages, your_birthday),
    offsetof(TextMessages, farms_name), offsetof(TextMessages, dogs_name),
};

static TitleBlockEntry title_block_entries[TITLE_BLOCK_COUNT] = {
    {1, &title_blocks[0]},
    {3, &title_blocks[1]},
    {0, &title_blocks[2]},
    {2, &title_blocks[3]},
};

static AnimState title_anim_0;
static AnimState title_anim_1;
static AnimState title_anim_2;

static AnimState title_column_a;
static AnimState title_column_b;
static AnimState title_column_c;
static AnimState title_anim_3;

static AnimState title_cursor_anim;
static u8 title_sprite_file[3360];
static u16 title_birth_text[640];

void title_step_dispatch(void) {
    title_step_handlers[game_state.progress.entryStep]();
}

static void title_reset_state(void) {
    title_reset_anim_counters();
    title_load_state = TITLE_LOAD_FADE_WAIT;
    title_sequence_state = TITLE_SEQ_FADE_IN;
    title_logo_frames = 0;
    title_menu_page = TITLE_MENU_CONTINUE;
    title_sequence_done = 0;
    title_saved_flags = 0;
}

static void title_reset_anim_counters(void) {
    title_logo_frames = 0;
    title_menu_page = TITLE_MENU_CONTINUE;
    title_anim_a_timer = 0;
    title_anim_b_timer = 0;
    title_anim_c_timer = 0;
    title_column_a_count = 0;
    title_column_b_count = 0;
    title_column_c_count = 0;
    title_logo_slide = -160;
    title_drop_count = 48;
    title_logo_wipe = 320;
}

/* Entry step: resets the title state. A fresh start (no continue flag) rebuilds the farm, the
 * new player, the options and the toolbox. */
static void title_enter_state(void) {
    s32 previous_flags;
    s32 saved_value;

    title_reset_state();
    previous_flags = game_state.globalFlags;
    title_saved_flags = previous_flags;
    game_state.globalFlags = previous_flags & ~GLOBAL_FLAG_DEMO_START;
    if (!(previous_flags & GLOBAL_FLAG_CONTINUE)) {
        saved_value = game_state.blockIndex;
        farm_state_init();
        game_state.blockIndex = saved_value;
        title_fill_field_layout(rand_range(3));
        title_player_reset_for_new_game();
        title_reset_world_options();
        title_copy_new_game_toolbox();
    }
    fade_start_out(0, 0, 2);
    menu_reset();
    title_image_request();
    game_state.globalFlags &= ~GLOBAL_FLAG_BIT12;
    game_state.progress.entryStep++;
}

/* Shows a random title picture once the sprite file is in. Continuing a saved game
 * skips straight to the next state; otherwise the picture fades in. */
static void title_state_show_image(void) {
    TitleImage *image;
    TitleImage *const *images;
    FrameState *framebuffer;
    FrameState *other;

    if (title_load_sprite_file() != 0) {
        image = (TitleImage *)&loading_data;
        images = title_image_ptrs;
        *image = *images[rand_range(3)];
        if (title_saved_flags & GLOBAL_FLAG_CONTINUE) {
            title_load_state = TITLE_LOAD_MUSIC;
            game_state.progress.entryStep++;
            return;
        }
        framebuffer = frame_records;
        other = framebuffer + 1;
        framebuffer->drawEnv.r0 = 0xFF;
        framebuffer->drawEnv.g0 = 0xFF;
        framebuffer->drawEnv.b0 = 0xFF;
        other->drawEnv.r0 = 0xFF;
        other->drawEnv.g0 = 0xFF;
        other->drawEnv.b0 = 0xFF;
        framebuffer[0].drawEnv.isbg = 1;
        framebuffer[1].drawEnv.isbg = 1;
        title_draw_logo();
        fade_start_in(30, 0, 2);
        title_load_state = TITLE_LOAD_FADE_WAIT;
        game_state.progress.entryStep++;
    }
}

/* Title-screen state machine, one step per frame (state in title_load_state). */
static void title_load_step(void) {
    s32 result;
    FrameState *framebuffer;
    FrameState *other;

    if (!(title_saved_flags & GLOBAL_FLAG_CONTINUE)) {
        title_draw_logo();
    }
    switch (title_load_state) {
    case TITLE_LOAD_FADE_WAIT:
        if (fade_is_settled() == 1) {
            title_load_state = TITLE_LOAD_BLOCK_START;
        }
        break;
    case TITLE_LOAD_BLOCK_START:
        title_load_block_start();
        title_load_state = TITLE_LOAD_BLOCK_WAIT;
        break;
    case TITLE_LOAD_BLOCK_WAIT:
        if (title_load_block_finish() != 0) {
            title_load_state = TITLE_LOAD_SMALL_START;
        }
        break;
    case TITLE_LOAD_SMALL_START:
        title_load_small_start();
        title_load_state = TITLE_LOAD_SMALL_WAIT;
        break;
    case TITLE_LOAD_SMALL_WAIT:
        if (title_load_small_finish() != 0) {
            title_load_state = TITLE_LOAD_IMAGE_START;
        }
        break;
    case TITLE_LOAD_IMAGE_START:
        title_load_image_start();
        title_load_state = TITLE_LOAD_IMAGE_WAIT;
        break;
    case TITLE_LOAD_IMAGE_WAIT:
        if (title_load_image_poll() != 0) {
            title_load_state = TITLE_LOAD_FUNC;
        }
        break;
    case TITLE_LOAD_FUNC:
        title_load_func_hook();
        title_load_state = TITLE_LOAD_COPY_BLOCK;
        break;
    case TITLE_LOAD_COPY_BLOCK:
        if (title_copy_block_for_state() != 0) {
            title_load_state = TITLE_LOAD_MUSIC;
        }
        break;
    case TITLE_LOAD_MUSIC:
        fade_start_out(30, 0, 2);
        title_start_music();
        title_load_state = TITLE_LOAD_SOUND_WAIT;
        break;
    case TITLE_LOAD_SOUND_WAIT:
        sound_load_tick();
        if (sound_fader_ready() != 0) {
            sound_fade_in(TITLE_FADE_FRAMES);
            title_load_state = TITLE_LOAD_SOUND_FADE_WAIT;
        }
        break;
    case TITLE_LOAD_SOUND_FADE_WAIT:
        if (sound_fader_mode() == SOUND_FADER_IDLE) {
            title_load_state = TITLE_LOAD_SCENE_FADE_WAIT;
        }
        break;
    case TITLE_LOAD_SCENE_FADE_WAIT:
        result = fade_is_settled();
        if (result == 1) {
            title_load_state = TITLE_LOAD_FADE_WAIT;
            sound_update();
            sound_seq_start_reverb(0, 0, 0x1A, 127);
            framebuffer = frame_records;
            other = framebuffer + 1;
            framebuffer->drawEnv.r0 = 0;
            framebuffer->drawEnv.g0 = 0;
            framebuffer->drawEnv.b0 = 0;
            other->drawEnv.r0 = 0;
            other->drawEnv.g0 = 0;
            other->drawEnv.b0 = 0;
            framebuffer[0].drawEnv.isbg = 1;
            framebuffer[1].drawEnv.isbg = 1;
            game_state.progress.entryStep++;
        }
        break;
    }
}

/* Title-screen state machine, stepped once per frame on title_sequence_state. */
static void title_sequence_step(void) {
    s32 buttons;
    s32 result;
    s32 next;

    menu_run_state();
    title_logo_frames = (title_logo_frames + 1) % TITLE_LOGO_WRAP;

    switch (title_sequence_state) {
    case TITLE_SEQ_FADE_IN:
        title_step_fn();
        fade_start_in(TITLE_FADE_FRAMES, 0, 2);
        title_sequence_state = TITLE_SEQ_FADE_IN_WAIT;
        break;
    case TITLE_SEQ_FADE_IN_WAIT:
        title_step_fn();
        if (fade_is_settled() == 1) {
            title_idle_frames = 0;
            title_sequence_state = TITLE_SEQ_IDLE;
        }
        break;
    case TITLE_SEQ_IDLE:
        title_idle_frames++;
        title_step_fn();
        if (input_pad1->pressed & (PAD_CROSS | PAD_START)) {
            sound_play(SOUND_MENU_CONFIRM);
            fade_start_out(TITLE_FADE_FRAMES, 0, 2);
            title_sequence_state = TITLE_SEQ_PRESS_FADE_WAIT;
        } else if (title_idle_frames >= TITLE_IDLE_FRAMES) {
            title_sequence_done = 1;
            title_sequence_state = TITLE_SEQ_DEMO_FADE_OUT;
        }
        break;
    case TITLE_SEQ_PRESS_FADE_WAIT:
        title_step_fn();
        if (fade_is_settled() == 1) {
            title_reset_anim_counters();
            title_sequence_state = TITLE_SEQ_SCENE_FADE_IN;
        }
        break;
    case TITLE_SEQ_SCENE_FADE_IN:
        title_draw_scene();
        fade_start_in(TITLE_FADE_FRAMES, 0, 2);
        title_sequence_state = TITLE_SEQ_SCENE_FADE_WAIT;
        break;
    case TITLE_SEQ_SCENE_FADE_WAIT:
        title_draw_scene();
        if (fade_is_settled() == 1) {
            title_logo_frames = 0;
            title_sequence_state = TITLE_SEQ_START_WAIT;
        }
        break;
    case TITLE_SEQ_START_WAIT:
        title_draw_scene();
        if (title_logo_frames >= TITLE_IDLE_FRAMES) {
            title_sequence_done = 1;
            title_sequence_state = TITLE_SEQ_DEMO_FADE_OUT;
        }
        if (input_pad1->pressed & PAD_START) {
            sound_play(SOUND_MENU_CONFIRM);
            title_reset_anim_counters();
            title_sequence_state = TITLE_SEQ_MENU;
        }
        break;
    case TITLE_SEQ_MENU:
        title_draw_all_menus();
        buttons = input_pad1->pressed;
        if (buttons & (PAD_UP | PAD_DOWN | PAD_SELECT)) {
            sound_play(SOUND_MENU_CURSOR);
            next = (u16)title_menu_page + 1;
            title_menu_page = next - (s16)next / 2 * 2;
        } else if (buttons & (PAD_START | PAD_CROSS)) {
            sound_play(SOUND_MENU_CONFIRM);
            if (title_menu_page == TITLE_MENU_NEW_GAME) {
                title_sequence_state = TITLE_SEQ_NEW_GAME;
            } else {
                fade_start_out(TITLE_FADE_FRAMES, 0, 2);
                sound_fade_out(TITLE_FADE_FRAMES);
                title_sequence_state = TITLE_SEQ_CONTINUE_FADE_WAIT;
            }
        }
        break;
    case TITLE_SEQ_NEW_GAME:
        title_draw_all_menus();
        title_sequence_state = TITLE_SEQ_NEW_GAME_TEXT_OPEN;
        break;
    case TITLE_SEQ_CONTINUE_FADE_WAIT:
        title_draw_all_menus();
        if (fade_is_settled() == 1) {
            title_sequence_state = TITLE_SEQ_CONTINUE_SOUND_WAIT;
        }
        break;
    case TITLE_SEQ_CONTINUE_SOUND_WAIT:
        if (sound_fader_mode() == SOUND_FADER_IDLE) {
            title_sequence_state = TITLE_SEQ_FADE_IN;
            game_state.progress.entryStep++;
        }
        break;
    case TITLE_SEQ_NEW_GAME_TEXT_OPEN:
        title_draw_anims();
        menu_request_open(3, 0x3A2);
        title_sequence_state = TITLE_SEQ_NEW_GAME_TEXT_WAIT;
        break;
    case TITLE_SEQ_NEW_GAME_TEXT_WAIT:
        title_draw_anims();
        if (menu_get_phase() == TEXT_WINDOW_CLOSED) {
            title_sequence_state = TITLE_SEQ_PLAYER_NAME_OPEN;
        }
        break;
    case TITLE_SEQ_PLAYER_NAME_OPEN:
        title_draw_anims();
        name_entry_reset();
        menu_request_open(3, 0x397);
        title_sequence_state = TITLE_SEQ_PLAYER_NAME_START;
        break;
    case TITLE_SEQ_PLAYER_NAME_START:
        title_draw_anims();
        if (menu_get_phase() == TEXT_WINDOW_CLOSED) {
            name_entry_start_no_cancel(game_state.player.name);
            title_sequence_state = TITLE_SEQ_PLAYER_NAME_ENTRY;
        }
        break;
    case TITLE_SEQ_PLAYER_NAME_ENTRY:
        title_draw_caption(0);
        title_draw_anims();
        if (name_entry_step() == NAME_STEP_ACCEPTED) {
            title_sequence_state = TITLE_SEQ_VOICE_OPEN;
        }
        break;
    case TITLE_SEQ_VOICE_OPEN:
        title_draw_anims();
        name_sound_reset();
        menu_request_open(3, 0x3A5);
        title_sequence_state = TITLE_SEQ_VOICE_WAIT;
        break;
    case TITLE_SEQ_VOICE_WAIT:
        title_draw_anims();
        if (menu_get_phase() == TEXT_WINDOW_CLOSED) {
            name_sound_begin((SoundSequence *)game_state.player.seq7C);
            title_sequence_state = TITLE_SEQ_VOICE_PLAY;
        }
        break;
    case TITLE_SEQ_VOICE_PLAY:
        title_draw_caption(1);
        title_draw_anims();
        result = name_sound_step();
        if (result == NAME_STEP_CANCELLED) {
            title_sequence_state = TITLE_SEQ_PLAYER_NAME_OPEN;
        } else if (result == NAME_STEP_ACCEPTED) {
            title_sequence_state = TITLE_SEQ_FARM_NAME_OPEN;
        }
        break;
    case TITLE_SEQ_FARM_NAME_OPEN:
        title_draw_anims();
        name_entry_reset();
        menu_request_open(3, 0x3A4);
        title_sequence_state = TITLE_SEQ_FARM_NAME_START;
        break;
    case TITLE_SEQ_FARM_NAME_START:
        title_draw_anims();
        if (menu_get_phase() == TEXT_WINDOW_CLOSED) {
            name_entry_start(game_state.progress.estate.farmName);
            title_sequence_state = TITLE_SEQ_FARM_NAME_ENTRY;
        }
        break;
    case TITLE_SEQ_FARM_NAME_ENTRY:
        title_draw_caption(2);
        title_draw_anims();
        switch (name_entry_step()) {
        case NAME_STEP_CANCELLED:
            title_sequence_state = TITLE_SEQ_VOICE_OPEN;
            break;
        case NAME_STEP_ACCEPTED:
            title_sequence_state = TITLE_SEQ_DOG_NAME_OPEN;
            break;
        }
        break;
    case TITLE_SEQ_DOG_NAME_OPEN:
        title_draw_anims();
        name_entry_reset();
        menu_request_open(3, 0x3A3);
        title_sequence_state = TITLE_SEQ_DOG_NAME_START;
        break;
    case TITLE_SEQ_DOG_NAME_START:
        title_draw_anims();
        if (menu_get_phase() == TEXT_WINDOW_CLOSED) {
            name_entry_start_cancellable(game_state.animals.dog.actor.name);
            title_sequence_state = TITLE_SEQ_DOG_NAME_ENTRY;
        }
        break;
    case TITLE_SEQ_DOG_NAME_ENTRY:
        title_draw_caption(3);
        title_draw_anims();
        switch (name_entry_step()) {
        case NAME_STEP_CANCELLED:
            title_sequence_state = TITLE_SEQ_FARM_NAME_OPEN;
            break;
        case NAME_STEP_ACCEPTED:
            title_sequence_state = TITLE_SEQ_BIRTHDAY_OPEN;
            break;
        }
        break;
    case TITLE_SEQ_BIRTHDAY_OPEN:
        title_draw_anims();
        title_draw_birthday();
        name_entry_reset();
        menu_request_open(3, 0x3AA);
        title_sequence_state = TITLE_SEQ_BIRTHDAY_CONFIRM;
        break;
    case TITLE_SEQ_BIRTHDAY_CONFIRM:
        title_draw_anims();
        title_draw_birthday();
        if (menu_get_phase() == TEXT_WINDOW_CLOSED) {
            if ((s16)menu_choice() == 1) {
                fade_start_out(TITLE_FADE_FRAMES, 0, 2);
                sound_fade_out(TITLE_FADE_FRAMES);
                title_sequence_state = TITLE_SEQ_NEW_GAME_FADE_WAIT;
            } else {
                title_sequence_state = TITLE_SEQ_PLAYER_NAME_OPEN;
            }
        }
        break;
    case TITLE_SEQ_NEW_GAME_FADE_WAIT:
        title_draw_anims();
        if (fade_is_settled() == 1) {
            title_sequence_state = TITLE_SEQ_NEW_GAME_LEAVE;
        }
        break;
    case TITLE_SEQ_NEW_GAME_LEAVE:
        if (sound_fader_mode() == SOUND_FADER_IDLE) {
            game_state.globalFlags |= GLOBAL_FLAG_NEW_GAME;
            title_sequence_state = TITLE_SEQ_FADE_IN;
            game_state.progress.entryStep++;
        }
        break;
    case TITLE_SEQ_RESTART_WAIT:
        if (input_pad1->pressed & PAD_START) {
            title_reset_anim_counters();
            title_sequence_state = TITLE_SEQ_SCENE_FADE_IN;
        }
        break;
    case TITLE_SEQ_DEMO_FADE_OUT:
        title_step_fn();
        fade_start_out(TITLE_FADE_FRAMES, 0, 2);
        sound_fade_out(TITLE_FADE_FRAMES);
        title_sequence_state = TITLE_SEQ_DEMO_FADE_WAIT;
        break;
    case TITLE_SEQ_DEMO_FADE_WAIT:
        title_step_fn();
        if (fade_is_settled() == 1) {
            title_sequence_state = TITLE_SEQ_DEMO_LEAVE;
        }
        break;
    case TITLE_SEQ_DEMO_LEAVE:
        if (sound_fader_mode() == SOUND_FADER_IDLE) {
            if (game_state.globalFlags & GLOBAL_FLAG_CONTINUE) {
                game_state.globalFlags &= ~GLOBAL_FLAG_CONTINUE;
            }
            title_sequence_state = TITLE_SEQ_FADE_IN;
            game_state.progress.entryStep++;
        }
        break;
    }
}

/* The two steps that end a scene: start the screen and the music fading out, then wait until
 * both have settled, stop the music and release its bank, and move on. */
static void title_exit_fade_begin(void) {
    fade_start_out(10, 0, 2);
    sound_fade_out(10);
    game_state.progress.entryStep++;
}

static void title_exit_fade_wait(void) {
    u8 count = (fade_is_settled() == 1);

    if (sound_fader_mode() == SOUND_FADER_IDLE) {
        count = (count + 1) & 0xFF;
    }
    if (count == 2) {
        sound_seq_stop_first(0);
        sound_update();
        sound_release_from(2, 0);
        game_state.progress.entryStep++;
    }
}

/* Leaves the title for the next scene. A demo, or a new game from the menu's first row, goes to
 * the farm (a new game also rolls four random words at the head of game_state); a continue
 * goes to the load screen. */
static void title_exit_finish(void) {
    s16 *queue;
    s32 count;
    s32 state_word;

    game_state.statusFlags &= ~STATUS_FLAG_DEBUG_EVENTS_300_AND_UP;
    if (title_sequence_done != 0) {
        game_state.globalFlags |= GLOBAL_FLAG_DEMO_START;
        game_state.demo->frame = 0;
        game_state.statusFlags |= STATUS_FLAG_DEBUG_EVENTS_300_AND_UP;
        title_fill_field_layout(TITLE_LAYOUT_DEMO);
    }
    game_state.progress.entryStep = 0;
    if (title_menu_page == TITLE_MENU_NEW_GAME) {
        state_word = game_state.globalFlags;
        if (state_word & GLOBAL_FLAG_CONTINUE) {
            game_state.globalFlags = state_word & ~GLOBAL_FLAG_CONTINUE;
        }
        queue = (s16 *)&game_state;
        count = 3;
        do {
            *queue = rand_range(65535);
            count -= 1;
            queue += 1;
        } while (count >= 0);
        main_request_scene(SCENE_FARM);
        return;
    }
    state_word = game_state.globalFlags;
    if (state_word & GLOBAL_FLAG_DEMO_START) {
        title_fill_field_layout(TITLE_LAYOUT_DEMO);
        main_request_scene(SCENE_FARM);
        return;
    }
    game_state.globalFlags = state_word | GLOBAL_FLAG_CONTINUE;
    main_request_scene(SCENE_LOAD);
}

static void title_logo_begin(void) {
    title_draw_anims();
    title_logo_frames = 0;
    title_step_fn = title_logo_wait;
}

static void title_logo_wait(void) {
    title_draw_anims();
    if (title_logo_frames >= TITLE_LOGO_WAIT_FRAMES) {
        title_step_fn = title_logo_slide_in;
    }
}

static void title_logo_slide_in(void) {
    title_draw_anims();
    title_draw_logo_slide(title_logo_slide);
    if (++title_logo_slide >= 0) {
        title_step_fn = title_logo_drop;
    }
}

static void title_logo_drop(void) {
    title_draw_anims();
    title_draw_logo_slide(0);
    title_draw_logo_drop(title_drop_count);
    if (--title_drop_count <= 0) {
        title_step_fn = title_logo_wipe_out;
    }
}

static void title_logo_wipe_out(void) {
    title_draw_anims();
    title_draw_logo_slide(0);
    title_draw_logo_drop(0);
    title_draw_logo_wipe(title_logo_wipe);
    title_logo_wipe -= 2;
    if (title_logo_wipe <= 0) {
        title_logo_frames = 0;
        title_step_fn = title_logo_blink;
    }
}

static void title_logo_blink(void) {
    title_draw_anims();
    title_draw_logo_slide(0);
    title_draw_logo_drop(0);
    if (title_logo_frames % TITLE_BLINK_PERIOD < TITLE_BLINK_ON) {
        title_draw_logo_wipe(0);
    }
    if (title_logo_frames >= TITLE_BLINK_END_FRAMES) {
        title_step_fn = title_logo_wipe_end;
    }
}

static void title_logo_wipe_end(void) {
    s16 t;
    title_draw_anims();
    title_draw_logo_slide(0);
    title_draw_logo_drop(0);
    title_draw_logo_wipe(title_logo_wipe);
    title_logo_wipe -= 2;
    t = title_logo_wipe;
    if (-HWD0 >= t) {
        title_step_fn = title_logo_reset;
    }
}

static void title_logo_reset(void) {
    title_draw_anims();
    title_draw_logo_slide(0);
    title_draw_logo_drop(0);
    title_logo_wipe = 320;
    title_step_fn = title_logo_wipe_out;
}

/* Draws the new game summary with the player's birthday. */
static void title_draw_birthday(void) {
    u_long *display;
    display = &current_frame->otTags[0][32];
    text_set_spacing(0, 1);
    window_frame_draw_at(&current_frame->otTags[0][33], 1, 72, 56, 176, 90);
    text_draw_plain(display, LOCALIZED(text_bank.messages.new_game_summary), 76, 60);
    text_set_spacing(0, 0);
    ui_draw_icon_2b_sub(display, 172, 72, game_state.player.birthday.season);
    title_birth_text[0] = 0x71;
    *text_format_number(game_state.player.birthday.day + 1, &title_birth_text[1], 2) = 0xFFFF;
    text_draw_plain(display, title_birth_text, 188, 72);
}

static void title_draw_all_menus(void) {
    title_draw_logo_slide(0);
    title_draw_logo_drop(0);
    title_draw_bg_scroll();
    title_anim_sprite_a();
    title_anim_sprite_b();
    title_anim_sprite_c();
    title_anim_columns();
    title_draw_menu_cursor();
    title_draw_menu_sprite_a();
    title_draw_menu_sprite_b();
}

static void title_draw_scene(void) {
    title_draw_logo_slide(0);
    title_draw_logo_drop(0);
    title_draw_bg_scroll();
    title_anim_sprite_a();
    title_anim_sprite_b();
    title_anim_sprite_c();
    title_anim_columns();
    title_draw_logo_wipe(0);
}

static void title_draw_anims(void) {
    title_draw_bg_scroll();
    title_anim_sprite_a();
    title_anim_sprite_b();
    title_anim_sprite_c();
    title_anim_columns();
}

static void title_draw_logo(void) {
    anim_draw_sprt_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x1E, 0, 0, 0);
}

static void title_draw_logo_drop(s16 drop) {
    anim_draw_sprt_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x20, 0, 0, drop);
}

static void title_draw_logo_slide(s16 slide) {
    anim_draw_sprt_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x1F, 0, 0, slide);
}

static void title_draw_logo_wipe(s16 wipe) {
    anim_draw_sprt_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x21, 0, wipe, 0);
}

/* Scrolls the two 3x3 tile layers of the title background. Layer A wobbles with a
 * cosine, layer B with a sine. */
static void title_draw_bg_scroll(void) {
    u_long *ot;
    s16 band_a;
    s16 band_b;
    s16 laps_a;
    s16 laps_b;
    s16 top;
    s16 left;

    band_a = title_scroll_a / 240;
    top = band_a * 240 - title_scroll_a;
    left = 320 - band_a * 80;
    ot = &current_frame->otTags[0][36];
    left = left + ccos((title_scroll_b << 12) / 120) * 12 / 4096;
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - left, top);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - (s16)(left - 320), top);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - (s16)(left - 640), top);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - left, top + 240);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - (s16)(left - 320), top + 240);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - (s16)(left - 640), top + 240);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - left, top + 480);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - (s16)(left - 320), top + 480);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top - (s16)(left - 640), top + 480);
    if (game_state.frameCount & 1) {
        title_scroll_a++;
        laps_a = title_scroll_a / 960;
        title_scroll_a -= laps_a * 960;
    }

    band_b = title_scroll_b / 240;
    top = title_scroll_b - band_b * 240;
    left = 320 - band_b * 80;
    left = left + csin((title_scroll_b << 12) / 120) * 12 / 4096;
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + left, top);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + (s16)(left - 320), top);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + (s16)(left - 640), top);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + left, top - 240);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + (s16)(left - 320), top - 240);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + (s16)(left - 640), top - 240);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + left, top - 480);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + (s16)(left - 320), top - 480);
    anim_draw_sprt_cursor(ot, &title_cursor_anim, 0x25, 0, top + (s16)(left - 640), top - 480);
    title_scroll_b++;
    laps_b = title_scroll_b / 960;
    title_scroll_b -= laps_b * 960;
    anim_draw_sprt_cursor(&current_frame->otTags[0][37], &title_cursor_anim, 0x1D, 0, 0, 0);
}

/* Advance the title animation counter and update the title-screen sprite. */
static void title_anim_sprite_a(void) {
    u32 frame;
    s32 quotient;
    s32 random_value;
    s16 mode;

    frame = (u16)title_anim_a_timer + 1;
    quotient = (s16)frame / 1800;
    frame = frame - quotient * 1800;
    title_anim_a_timer = frame;
    anim_draw_ft4_advance(&current_frame->otTags[0][35], &title_anim_0, 282, 173);
    if (title_anim_a_timer < 90) {
        return;
    }
    title_anim_a_timer = 0;
    random_value = rand_range(10);
    mode = random_value;
    if (mode == (s16)(((s32)mode + ((u32)(random_value << 16) >> 31)) >> 1) * 2) {
        mode--;
    }
    if (mode < 0) {
        mode = 0;
    }
    anim_select_range(&title_anim_0, mode & 0xFF);
}

/* Advance the title animation and refresh its displayed frame. */
static void title_anim_sprite_b(void) {
    u32 frame;
    s32 random_value;
    s16 mode;

    frame = (u16)title_anim_b_timer + 1;
    frame = frame - ((s16)frame / 1800) * 1800;
    title_anim_b_timer = frame;
    anim_draw_ft4_advance(&current_frame->otTags[0][35], &title_anim_1, 33, 146);
    if (title_anim_b_timer < 60) return;
    title_anim_b_timer = 0;
    random_value = rand_range(9) + 10;
    mode = random_value;
    if (mode == (((s32)(mode + ((u32)(random_value << 16) >> 31)) >> 1) * 2)) {
        mode--;
    }
    if (mode < 10) {
        mode = 0xA;
    }
    anim_select_range(&title_anim_1, mode & 0xFF);
}

/* Advance the third title sprite and pick a new frame (19..21) every 60 frames; a pick of 19 makes
 * the next wait 30 frames. */
static void title_anim_sprite_c(void) {
    u32 frame;
    s16 mode;
    frame = (u16)title_anim_c_timer + 1;
    frame = frame - ((s16)frame / 1800) * 1800;
    title_anim_c_timer = frame;
    anim_draw_ft4_advance(&current_frame->otTags[0][35], &title_anim_2, 51, 182);
    frame = title_anim_c_timer;
    if ((s16)frame >= 60) {
        title_anim_c_timer = 0;
        mode = rand_range(3) + 19;
        if (mode == 0x13) {
            title_anim_c_timer = 30;
        }
        anim_select_range(&title_anim_2, mode & 0xFF);
    }
}

static void title_anim_columns(void) {
    title_anim_column_a();
    title_anim_column_b();
    title_anim_column_c();
}

/* Advance the first title animation column and request its next frame. */
static void title_anim_column_a(void) {
    s32 frame;
    u_long *drawing_area;

    frame = (u16)title_column_a_count + 1;
    frame = frame - ((s16)frame / 1800) * 1800;
    title_column_a_count = frame;
    drawing_area = &current_frame->otTags[0][35];
    anim_draw_ft4_advance(drawing_area, &title_column_a, 295, 205);
    anim_draw_ft4_advance(drawing_area, &title_column_a, 258, 138);
    anim_draw_ft4_advance(drawing_area, &title_column_a, 280, 121);
    if (title_column_a_count >= 15) {
        title_column_a_count = 0;
        anim_select_range(&title_column_a, (rand_range(2) + 0x16) & 0xFF);
    }
}

/* Advance the second title animation column (five columns, with a longer dwell
 * than the first) and request its next frame. */
static void title_anim_column_b(void) {
    s32 frame;
    u_long *drawing_area;

    frame = (u16)title_column_b_count + 1;
    frame = frame - ((s16)frame / 1800) * 1800;
    title_column_b_count = frame;
    drawing_area = &current_frame->otTags[0][35];
    anim_draw_ft4_advance(drawing_area, &title_column_b, 63, 149);
    anim_draw_ft4_advance(drawing_area, &title_column_b, 10, 188);
    anim_draw_ft4_advance(drawing_area, &title_column_b, 9, 214);
    anim_draw_ft4_advance(drawing_area, &title_column_b, 295, 52);
    anim_draw_ft4_advance(drawing_area, &title_column_b, 294, 30);
    if (title_column_b_count >= 20) {
        title_column_b_count = 0;
        anim_select_range(&title_column_b, (rand_range(2) + 0x18) & 0xFF);
    }
}

/* Advance the third title animation column and request its next frame. */
static void title_anim_column_c(void) {
    s32 frame;
    u_long *drawing_area;

    frame = (u16)title_column_c_count + 1;
    frame = frame - ((s16)frame / 1800) * 1800;
    title_column_c_count = frame;
    drawing_area = &current_frame->otTags[0][35];
    anim_draw_ft4_advance(drawing_area, &title_column_c, 23, 30);
    anim_draw_ft4_advance(drawing_area, &title_column_c, 6, 109);
    anim_draw_ft4_advance(drawing_area, &title_column_c, 36, 223);
    if (title_column_c_count >= 30) {
        title_column_c_count = 0;
        anim_select_range(&title_column_c, (rand_range(2) + 0x1A) & 0xFF);
    }
}

/* Draws the menu cursor, blinking every 30 frames. Its draw priority depends on the menu row. */
static void title_draw_menu_cursor(void) {
    s32 frame_count;
    s32 duration;
    s32 priority;

    frame_count = title_logo_frames;
    duration = 104;
    if (frame_count % 30 < 15) {
        duration = 100;
    }
    priority = 179;
    if (title_menu_page == TITLE_MENU_NEW_GAME) {
        priority = 155;
    }
    anim_draw_ft4_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x24, 0, duration, priority, 0x1000, 0, 0);
}

static void title_draw_menu_sprite_a(void) {
    anim_draw_sprt_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x22, 0, 0, 0);
}

static void title_draw_menu_sprite_b(void) {
    anim_draw_sprt_cursor(&current_frame->otTags[0][34], &title_cursor_anim, 0x23, 0, 0, 0);
}

/* Draws one of the four name-entry captions. */
static void title_draw_caption(s16 caption) {
    u16 *text;

    text = TEXT_AT_OFFSET(text_bank_starts.messages + title_caption_offsets[caption]);
    window_frame_draw_at(&current_frame->otTags[0][1], 1, 16, 16, 120, 20);
    text_draw_plain(current_frame->otTags[0], text, 20, 20);
}

/* Where the scene's image starts in A_FILE member 0, and its size. */
#define SCENE_IMAGE_SECTOR 0x2000
#define SCENE_IMAGE_SIZE 0x23000

/* Wait for the display to finish, clear the ordering table and start reading the scene's
 * image into the staging buffer. The next step collects it. */
static void title_image_request(void) {
    DrawSync(0);
    ClearOTagR(current_frame->ot, FRAME_OT_DEPTH);
    afile_read_bytes(0, SCENE_IMAGE_SECTOR, SCENE_IMAGE_SIZE, STAGING_BUFFER, 1, 1);
}

/* Loads the title sprite file and its texture pack, then binds the animations to the file and
 * selects their first frames. */
static s32 title_load_sprite_file(void) {
    if (afile_read_bytes(0, SCENE_IMAGE_SECTOR, SCENE_IMAGE_SIZE, region_base + 17040, 1, 0) == 0) {
        return 0;
    }
    texture_pack_load(region_base + 0x4FAC);
    *(TitleSpriteFile *)title_sprite_file = *(TitleSpriteFile *)(region_base + 0x4290);
    anim_bind_file(&title_anim_0, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_anim_1, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_anim_2, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_column_a, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_column_b, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_column_c, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_anim_3, (AnimFile *)title_sprite_file);
    anim_bind_file(&title_cursor_anim, (AnimFile *)title_sprite_file);
    anim_select_range(&title_anim_0, 0);
    anim_select_range(&title_anim_1, 0xA);
    anim_select_range(&title_anim_2, 0x13);
    anim_select_range(&title_column_a, 0x16);
    anim_select_range(&title_column_b, 0x18);
    anim_select_range(&title_column_c, 0x1A);
    anim_select_range(&title_anim_3, 0x1C);
    anim_select_range(&title_cursor_anim, 0x1D);
    return 1;
}

static void title_start_music(void) {
    sound_set_seq_arg(0, STAGING_BUFFER);
    sound_request(SOUND_REQUEST_RESET, 0);
    sound_request(SOUND_REQUEST_SEQ_1, 0);
    sound_request(SONG_TITLE, 0);
}

static void title_load_image_start(void) {
    DrawSync(0);
    ClearOTagR(current_frame->ot, FRAME_OT_DEPTH);
    afile_read_bytes(0, 0x2A800, 0x49000, farm_area.loadWindow, 1, 1);
}

static int title_load_image_poll(void) {
    return afile_read_bytes(0, 0x2A800, 0x49000, farm_area.loadWindow, 1, 0) != 0;
}

static void title_load_block_start(void) {
    FrameState **addr;
    FrameState *p;
    DrawSync(0);
    addr = &current_frame;
    p = *addr;
    ClearOTagR(p->ot, FRAME_OT_DEPTH);
    afile_read_bytes(0, 0x25000, 0x5800, STAGING_BUFFER, 1, 1);
}

static s32 title_load_block_finish(void) {
    if (afile_read_bytes(0, 0x25000, 0x5800, region_base + 17040, 1, 0) == 0) {
        return 0;
    }
    texture_pack_load(region_base + 0x566C);
    *(TitleImageBuffer *)farm_area.stageData = *(TitleImageBuffer *)(region_base + 0x4290);
    return 1;
}

static void title_load_small_start(void) {
    FrameState *p;
    DrawSync(0);
    p = current_frame;
    ClearOTagR(p->ot, FRAME_OT_DEPTH);
    afile_read_bytes(0, 0, 0x2000, STAGING_BUFFER, 1, 1);
}

static int title_load_small_finish(void) {
    if (afile_read_bytes(0, 0, 0x2000, STAGING_BUFFER, 1, 0)) {
        texture_pack_load(STAGING_BUFFER);
        return 1;
    }
    return 0;
}

/* Empty hook, kept as a load step. */
static void title_load_func_hook(void) {
}

/* Copies the demo recording block for blockIndex (clamped to the table) and moves blockIndex on
 * to the block's next index. */
static s32 title_copy_block_for_state(void) {
    s32 i = game_state.blockIndex;
    i = (i < 0) ? 0 : (i >= TITLE_BLOCK_COUNT) ? TITLE_BLOCK_COUNT - 1 : i;

    game_state.demo->recording.copy = *title_block_entries[i].src;
    game_state.blockIndex = title_block_entries[i].next;
    return 1;
}

/* Fills the field grid from one of the four title layouts. Cells that hold a crop get tilled
 * soil under them and their crop's growth stage. */
static void title_fill_field_layout(s32 layout) {
    const u16 *source;
    FarmFieldTile *cell;
    s32 row;
    s32 col;
    u8 kind;

    switch (layout) {
    case TITLE_LAYOUT_NEW_1:
        source = title_layout1_cells;
        break;
    case TITLE_LAYOUT_NEW_2:
        source = title_layout2_cells;
        break;
    case TITLE_LAYOUT_DEMO:
        source = title_layout3_cells;
        break;
    case TITLE_LAYOUT_NEW_0:
    default:
        source = title_layout0_cells;
        break;
    }

    for (row = 0; row < FIELD_ROWS; row++) {
        for (col = 0; col < FIELD_COLS; col++, source++) {
            cell = &game_state.fieldTiles[row].rows[col];
            cell->value = ITEM_SOIL;
            cell->ground = ITEM_SOIL;
            cell->kind = 0;
            cell->unused5 = 0;
            cell->growthFlags = 0;
            cell->value = *source;
            if ((u16)(cell->value - 34) < 15) {
                kind = game_state.cropTable[game_state.itemInfo[cell->value].crop].grownStage;
                cell->ground = ITEM_TILLED_SOIL;
                cell->kind = kind;
            }
        }
    }
}

static void title_player_reset_for_new_game(void) {
    FarmPlayer *player = &game_state.player;
    u32 i;

    player->stateFlags = 0;
    player->latches = 0;
    player->fatigue = 0;
    player->toolCharge = 0;
    player->idleFrames = 0;
    player->modeState = 0;
    player->facing38 = FACING_DOWN;
    player->prevFacing3A = 0;
    player->mode = 0;
    player->previousMode = 0;
    player->target = 0;
    player->targetFlags = 0;
    player->talkVillager = -1;
    player->talkAnimal = 0;
    player->stamina = TITLE_START_STAMINA;
    player->maxStamina = TITLE_START_STAMINA;
    player->happiness = 0;
    player->gold = TITLE_START_GOLD;
    player->wedding.bride = -1;
    player->scriptSteps = 0;
    player->sleptAt = 0;
    player->wokeAt = game_state.progress.clock.minuteOfDay;
    for (i = 0; i < 2; i++) {
        player->held[i].id = 0;
        player->held[i].modifier = 0;
        player->held[i].count = 0;
    }
    for (i = 0; i < 8; i++) {
        player->tools[i].id = 0;
        player->tools[i].modifier = 0;
        player->tools[i].count = 0;
        player->items[i].id = 0;
        player->items[i].modifier = 0;
        player->items[i].count = 0;
    }
    player->place.location = PLACE_FARM;
    player->shown.id = 0;
    player->shown.modifier = 0;
    player->shown.count = 0;
    player->place.value = 0;
    player->rucksackLevel = 0;
    player->itemSlots = 2;
    for (i = 0; i < 5; i++) {
        player->toolExp[i] = 0;
    }
    player->cue.id = -1;
    player->cue.phase = 0;
    for (i = 0; i < 10; i++) {
        player->trail[i].vx = 0;
        player->trail[i].vy = 0;
        player->trail[i].vz = 0;
    }
    player->chickToy = 0;
    player->wedding.date.year = -1;
    player->wedding.date.season = -1;
    player->wedding.date.day = -1;
    player->wedding.groom = -1;
    player->wedding.bride = -1;
    player->currentAction = 0;
}

/* Sets the options to their new-game values and the sound to stereo. */
static void title_reset_world_options(void) {
    game_state.world.options.messageType = 0;
    game_state.world.options.vibration = 1;
    game_state.world.options.stereo = 1;
    game_state.world.options.statusLatch = 1;
    sound_set_stereo();
}

/* Copies the new game's starting toolbox items into the estate's toolbox store. */
static void title_copy_new_game_toolbox(void) {
    u32 i = 0;
    FarmState *d = &game_state;
    FarmStoredItem *dst = d->progress.estate.toolboxItems;
    FarmStoredItem *src = title_new_game_toolbox;
    do {
        *dst = *src;
        dst++;
        i++;
        src++;
    } while (i < 5U);
}
